import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`newborn-photographer`,heroTitle:`Grow your newborn photography business in minutes`,heroSubtitle:`Perplexity Computer reviews your newborn photography website, portfolio, packages, booking flow, and local visibility, then builds a plan to attract more families.`,inputUrlCta:`Grow my photography business`,inputUrlPlaceholder:`yourphotographysite.com`,inputUrlPrefill:`Go to {url} and run a full growth audit for this newborn photography business. 1) Review the website for portfolio presentation, package clarity, safety and trust signals, pricing guidance, mobile UX, and inquiry friction. 2) Audit local SEO, Google Business Profile signals, reviews, social proof, and lead magnet opportunities. 3) Compare against top nearby newborn photographers for positioning, package structure, galleries, and inquiry CTAs. 4) Recommend the highest-impact fixes for more qualified inquiries, session bookings, and repeat family clients. 5) Deliver a prioritized action plan with rewritten copy, portfolio recommendations, and growth ideas.`,heroOverlaySteps:[`Reviewing your newborn photography site, portfolio, packages, and inquiry flow`,`Benchmarking nearby photographers on trust, galleries, reviews, and visibility`,`Finding the copy, package, and UX gaps holding back qualified inquiries`,`Portfolio updates, booking fixes, and local visibility priorities ready to use`],generatingSteps:[`Visiting {url} to inspect your photography website, portfolio, and inquiry path`,`Designing an agent to compare nearby photographers, packages, and local signals`,`Configuring portfolio recommendations, copy rewrites, and booking-flow fixes`,`Setting up a prioritized action plan for more newborn session inquiries`],featureSectionTitle:`From expecting parents to booked sessions`,featureCardTitles:[`Connects to your photography stack`,`Fixes you can launch now`],featureCardDescriptions:[`Computer separates your newborn photography audit into site review, portfolio analysis, package positioning, local SEO, and competitor research, then routes each step to the right model.`,`Google Business Profile, inquiry forms, Docs, Sheets, and planning tools can all feed one workflow so recommendations stay organized.`,`Portfolio updates. Package rewrites. Inquiry-flow improvements. Local SEO priorities. Computer gives you updates tied to more qualified bookings.`],capabilitySectionTitle:`Your newborn photography growth team, on autopilot`,capabilitySectionSubtitle:`Paste your photography URL, step away, and come back to a clearer plan to book more newborn sessions.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review portfolio presentation, package clarity, safety cues, pricing guidance, inquiry flow, and mobile UX.`},{title:`Portfolio Positioning`,description:`Computer can identify gallery, copy, and trust improvements that help expecting parents feel confident enough to inquire.`},{title:`Local Search Review`,description:`Computer can assess Google Business Profile strength, reviews, and local SEO signals against nearby newborn photographers.`},{title:`Connect Your Tools`,description:`Computer can organize recommendations across Google Business Profile, inquiry tools, Docs, and Sheets so your team can execute quickly.`},{title:`Remember Your Style`,description:`Computer can remember your session types, editing style, package structure, and ideal client profile for future growth audits.`},{title:`Monitor Inquiry Signals`,description:`Computer can revisit your online presence over time, flag when conversion signals slip, and suggest the next fix most likely to improve inquiries.`}]});export{t as default};
